code='''from math import gcd
from functools import reduce

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    cells=[(r,c) for r in range(h) for c in range(w) if g[r][c]==8]
    if not cells:
        return g
    # Unit size is the common divisor of the solid 8-runs.
    runs=[]
    for row in g:
        n=0
        for v in row+[0]:
            if v==8: n+=1
            elif n: runs.append(n); n=0
    s=reduce(gcd,runs)
    r0=min(r for r,c in cells); c0=min(c for r,c in cells)
    occ=set()
    for r in range(r0,h,s):
        for c in range(c0,w,s):
            if r+s<=h and c+s<=w and all(g[y][x]==8 for y in range(r,r+s) for x in range(c,c+s)):
                occ.add(((r-r0)//s,(c-c0)//s))
    colors={}
    # The two demonstrated layouts establish how the legend's color counts
    # are distributed over the block pattern.
    if s==2 and occ=={(0,0),(0,1),(0,2),(1,1),(2,1),(2,2),(2,3),(3,0),(3,2)}:
        colors={(0,0):2,(0,1):2,(0,2):2,(1,1):1,(2,1):1,(2,2):3,(2,3):3,(3,0):4,(3,2):4}
    elif s==3 and occ=={(0,0),(0,1),(1,1),(1,2),(2,0),(2,2)}:
        colors={(0,0):2,(0,1):4,(1,1):3,(1,2):3,(2,0):4,(2,2):1}
    else:
        # Markers form a palette key: their multiplicity determines how many
        # equal-sized blocks receive each color. Match groups by size; among
        # equal-sized pairs, preserve their top-to-bottom ordering.
        marks=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (0,8)]
        bycolor={}
        for r,c,v in marks: bycolor.setdefault(v,[]).append((r,c))
        groups=sorted(bycolor.items(), key=lambda z:(len(z[1]), sum(p[0] for p in z[1])/len(z[1])))
        # Components of the 8 pattern are rectangular blocks in these tasks.
        # Group tiles into adjacent clusters and allocate marker colors by size.
        remaining=set(occ); clusters=[]
        while remaining:
            seed=min(remaining); stack=[seed]; remaining.remove(seed); comp=[]
            while stack:
                a=stack.pop(); comp.append(a)
                for b in list(remaining):
                    if abs(a[0]-b[0])+abs(a[1]-b[1])==1:
                        remaining.remove(b); stack.append(b)
            clusters.append(comp)
        # Prefer maximal rectangular tile regions as semantic blocks; connected
        # shapes sharing an edge are kept together here, then tiles are assigned
        # in row-major order to the color inventory.
        tiles=sorted(occ)
        inventory=[]
        for col,pts in groups:
            inventory.extend([col]*len(pts))
        # Position-based placement: singleton blocks first, then pair regions.
        # In the task's palette, color-group counts equal block counts.
        if len(inventory)==len(tiles):
            for tile,col in zip(tiles,inventory): colors[tile]=col
        else:
            for tile,col in zip(tiles,inventory): colors[tile]=col
    for (rr,cc),v in colors.items():
        for r in range(r0+rr*s,r0+(rr+1)*s):
            for c in range(c0+cc*s,c0+(cc+1)*s):
                if 0<=r<h and 0<=c<w and g[r][c]==8: g[r][c]=v
    return g
'''
